export function formatRagResult(
  result: RagQueryResult,
  verbose: boolean = false
): string {
  const lines: string[] = [];

  if (!result.ok) {
    lines.push(`❌ Error: ${result.error}`);
    if (result.code) {
      lines.push(`   Code: ${result.code}`);
    }
    return lines.join('\n');
  }

  const sep = '─'.repeat(60);
  lines.push(sep);
  lines.push(`📝 Response (${result.mode} mode):`);
  lines.push(sep);
  lines.push(result.response);
  lines.push('');

  if (result.citations.length > 0) {
    lines.push(`📚 Citations (${result.citations.length}):`);
    result.citations.slice(0, 5).forEach((citation, i) => {
      lines.push(`   [${i + 1}] ${citation.documentId} (relevance: ${citation.relevance.toFixed(2)})`);
    });
  }

  const meta = result.metadata;
  lines.push('');
  lines.push('📊 Metadata:');
  lines.push(`   Strategy: ${meta.strategy}`);
  lines.push(`   Iterations: ${meta.iterations}`);
  lines.push(`   Relevance Score: ${meta.relevanceScore.toFixed(2)}`);
  if (meta.groundingScore !== null) {
    lines.push(`   Grounding Score: ${meta.groundingScore.toFixed(2)}`);
  }

  const metrics = meta.metrics;
  lines.push(`   Latency: ${metrics.totalLatencyMs}ms`);
  lines.push(`   LLM Calls: ${metrics.llmCallCount}`);
  lines.push(`   Est. Cost: $${metrics.estimatedCost.toFixed(4)}`);

  if (meta.warnings.length > 0) {
    lines.push('');
    lines.push('⚠️ Warnings:');
    meta.warnings.forEach((warning) => {
      lines.push(`   - ${warning.type}: ${warning.message}`);
    });
  }

  if (verbose && meta.trace) {
    lines.push('');
    lines.push('🔍 Execution Trace:');
    meta.trace.forEach((entry) => {
      lines.push(`   → ${entry.node}${entry.message ? `: ${entry.message}` : ''}`);
    });
  }

  if (result.mock) {
    lines.push('');
    lines.push('ℹ️  Note: This is a mock response (TypeScript runner not available)');
  }

  return lines.join('\n');
}

